const MAX_CHARS = 700;
const OVERLAP_CHARS = 120;

function cleanText(text) {
  return (text || "")
    .replace(/\r/g, "\n")
    .replace(/[ \t]+/g, " ")
    .replace(/\n{3,}/g, "\n\n")
    .replace(/TechStore Brasil • Uso Exclusivo Interno Página \d+ de \d+/gi, "")
    .replace(/CONFIDENCIAL E DE USO INTERNO:[^\n]*/gi, "")
    .replace(/\[mailto:([^\]]+)\]\(mailto:[^)]+\)/gi, "$1")
    .trim();
}

function getLines(text) {
  return text
    .split("\n")
    .map(l => l.trim())
    .filter(Boolean);
}

function extractDocCode(text) {
  const lines = getLines(text);
  const firstLine = lines[0] || "";
  const match = firstLine.match(/\b([A-Z]{3}-\d{3})\b/);
  if (match) return match[1];

  const fallback = text.match(/\b([A-Z]{3}-\d{3})\b/);
  return fallback ? fallback[1] : "DOC-SEM-CODIGO";
}

function extractCategory(text) {
  const lines = getLines(text);
  if (lines.length >= 2) return lines[1];
  return "SEM_CATEGORIA";
}

function extractTitle(item, text) {
  const lines = getLines(text);

  if (item.info && item.info.Title) {
    return item.info.Title.trim();
  }

  if (lines.length >= 3) return lines[2];
  return "Documento sem título";
}

function extractSubtitle(text, title) {
  const lines = getLines(text);
  const idx = lines.findIndex(line => line === title);
  if (idx >= 0 && lines[idx + 1]) return lines[idx + 1];
  return "";
}

function splitBySections(text) {
  const regex = /(^|\n)(\d+\.\s+[^\n]+)/g;
  const matches = [...text.matchAll(regex)];

  if (matches.length === 0) {
    return [{ section: "Conteúdo Geral", content: text }];
  }

  const sections = [];

  for (let i = 0; i < matches.length; i++) {
    const start = matches[i].index + (matches[i][1] ? matches[i][1].length : 0);
    const end = i + 1 < matches.length ? matches[i + 1].index : text.length;
    const block = text.slice(start, end).trim();

    const sectionTitleMatch = block.match(/^(\d+\.\s+[^\n]+)/);
    const sectionTitle = sectionTitleMatch ? sectionTitleMatch[1].trim() : `Seção ${i + 1}`;

    sections.push({
      section: sectionTitle,
      content: block
    });
  }

  return sections;
}

function chunkText(text, maxChars, overlapChars) {
  const paragraphs = text
    .split(/\n+/)
    .map(p => p.trim())
    .filter(Boolean);

  const chunks = [];
  let current = "";

  for (const paragraph of paragraphs) {
    const candidate = current ? `${current}\n${paragraph}` : paragraph;

    if (candidate.length <= maxChars) {
      current = candidate;
      continue;
    }

    if (current) {
      chunks.push(current.trim());
    }

    if (paragraph.length <= maxChars) {
      current = paragraph;
      continue;
    }

    let start = 0;
    while (start < paragraph.length) {
      const end = start + maxChars;
      const slice = paragraph.slice(start, end).trim();
      if (slice) chunks.push(slice);

      if (end >= paragraph.length) break;
      start += maxChars - overlapChars;
    }

    current = "";
  }

  if (current) {
    chunks.push(current.trim());
  }

  return chunks;
}

function buildSearchableText(title, category, doc_code, section, chunk) {
  return `${title}. ${category}. ${doc_code}. ${section}. ${chunk}`;
}

const output = [];

for (const item of items) {
  const rawText = item.json.text || "";
  const cleaned = cleanText(rawText);

  const doc_code = extractDocCode(cleaned);
  const category = extractCategory(cleaned);
  const title = extractTitle(item.json, cleaned);
  const subtitle = extractSubtitle(cleaned, title);
  const source_file = `${doc_code}.pdf`;
  const total_pages = item.json.numpages || null;

  const sections = splitBySections(cleaned);

  let globalChunkIndex = 0;

  for (const sectionData of sections) {
    const sectionChunks = chunkText(sectionData.content, MAX_CHARS, OVERLAP_CHARS);

    for (let i = 0; i < sectionChunks.length; i++) {
      const content = sectionChunks[i];
      const searchable_text = buildSearchableText(
        title,
        category,
        doc_code,
        sectionData.section,
        content
      );

      output.push({
        json: {
          doc_code,
          title,
          subtitle,
          category,
          section: sectionData.section,
          chunk_index: globalChunkIndex,
          section_chunk_index: i,
          source_file,
          total_pages,
          content,
          content_length: content.length,
          searchable_text
        }
      });

      globalChunkIndex++;
    }
  }
}

return output;
